 935	function cpuMorph(out, A, B, t, s, i3, time, drift){
 936	  let lt = Math.min(1, Math.max(0, (t - s*0.38)/0.62));
 937	  lt = lt*lt*(3-2*lt);
 938	  const arc = Math.sin(lt*Math.PI);
 939	  out[i3]   = A[i3]   + (B[i3]  -A[i3])  *lt;
 940	  out[i3+1] = A[i3+1] + (B[i3+1]-A[i3+1])*lt;
 941	  out[i3+2] = A[i3+2] + (B[i3+2]-A[i3+2])*lt + arc*(0.35+0.5*s);
 942	  if(drift){ /* mirror the shader's idle displacement so picking stays synced */
 943	    out[i3]   += Math.sin(time*0.35 + s*39.0)*0.028;
 944	    out[i3+1] += Math.cos(time*0.29 + s*51.0)*0.028;
 945	    out[i3+2] += Math.sin(time*0.23 + s*67.0)*0.020;
 946	  }
 947	}
