728	function passes(g){
729	  const f = state.filter;
730	  if(f==="hits" && g.f===0) return false;
731	  if(f==="medium" && g.f!==1) return false;
732	  if(f==="unresolved" && g.f!==2) return false;
733	  if(f==="format" && g.f!==3) return false;
734	  if(["sanger18","sanger97","broad_gain","broad_loss"].includes(f) && !(g.tags||[]).includes(f)) return false;
735	  if(state.q && !g.g.toUpperCase().includes(state.q.toUpperCase())) return false;
736	  return true;
737	}
738	function renderTable(){
739	  const k = state.sortKey, dir = state.sortDir;
740	  let rows = GENES.filter(passes);
741	  rows.sort((a,b)=>{
742	    if(k==="g") return dir*String(a.g).localeCompare(String(b.g));
743	    if(k==="f") return dir*(a.f-b.f) || (Math.abs(b.D)-Math.abs(a.D));
744	    const x=a[k], y=b[k];
745	    if(x==null && y==null) return 0; if(x==null) return 1; if(y==null) return -1;
746	    if(k==="rA" || k==="bf") return dir*(y-x); /* signed: most-reproduced first */
747	    return dir*(Math.abs(y)-Math.abs(x)); /* dir=1: strongest effect first */
748	  });
749	  const show = rows.slice(0, state.shown);
750	  $("#gbody").innerHTML = show.map(g=>`<tr data-g="${g.g}"${g.g===state.selected?' class="sel"':""}>
751	    <td><button type="button" class="glink" data-g="${g.g}" aria-label="Open ${g.g} details">${g.g}</button></td><td><span class="badge ${FLAGS[g.f][1]}">${FLAGS[g.f][0]}</span></td>
752	    <td>${fmt(g.D)}</td><td>${fmt(g.A)}</td><td>${fmt(g.F)}</td>
753	    <td>${g.rA==null?"—":Math.round(g.rA*100)+"%"}</td><td>${pct(g.bf)}</td></tr>`).join("");
754	  $("#rowcount").textContent = `Showing ${show.length.toLocaleString()} of ${rows.length.toLocaleString()} genes` +
755	    (k==="rA"||k==="bf" ? " · sorted high to low" : (k!=="g"&&k!=="f" ? " · sorted by effect strength" : ""));
756	  $("#moreBtn").style.display = rows.length>state.shown ? "" : "none";
757	  document.querySelectorAll("#gbody tr").forEach(tr=> tr.onclick = ev=>{ if(ev.target.closest("button")) return; select(tr.dataset.g, false); });
758	  document.querySelectorAll("#gbody .glink").forEach(b=> b.onclick = ()=> select(b.dataset.g, false));
759	  document.querySelectorAll("th[data-sort]").forEach(th=>{
